export default function HeroArt({ t }: { t: TFunction }) {
  return (
    <div className="hero-art" aria-hidden="true">
      <svg viewBox="0 0 576 592" fill="none">
        <g opacity="0.6" stroke="var(--line)">
          {RINGS.map((r) => (
            <circle key={r} cx={CENTER.x} cy={CENTER.y} r={r} />
          ))}
          {SPOKES.map((d) => (
            <path key={d} d={d} />
          ))}
        </g>

        {/* Conexiones: se dibujan solas (pathLength=1 + stroke-dashoffset). */}
        {NODES.map((n, i) => (
          <path
            key={i}
            className={n.draw}
            d={n.d}
            pathLength={1}
            stroke={n.stroke}
            strokeWidth={n.width}
            strokeLinecap="round"
          />
        ))}

        {/* Núcleo AMG. */}
        <g className="pop">
          <circle cx={CENTER.x} cy={CENTER.y} r="59.5" fill="var(--paper)" stroke="var(--pine)" />
          <circle cx={CENTER.x} cy={CENTER.y} r="52.2" fill="var(--pine)" />
          <circle cx={CENTER.x} cy={CENTER.y} r="43.9" stroke="var(--paper)" />
          <path d={AMG_PATH} fill="var(--white)" />
        </g>

        {NODES.map((n, i) => (
          <g className={n.pop} key={i}>
            <circle
              cx={n.cx}
              cy={n.cy}
              r={n.r}
              fill={n.fill}
              stroke={n.ring}
              strokeWidth={n.ring ? 1.4 : undefined}
            />
            <text className="node-label" x={n.cx} y={n.labelY} textAnchor="middle" fill={n.labelFill}>
              {t(n.label)}
            </text>
          </g>
        ))}
      </svg>
    </div>
  );
}
